  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f6f3eb">
  <title>FIELD NOTES</title>
  <style>
    :root { color-scheme: light; --paper:#f6f3eb; --ink:#163b43; --accent:#bf4e2e; --rule:rgba(22,59,67,.25); --gutter:clamp(24px,4vw,64px); }
    * { box-sizing:border-box; }
    [hidden] { display:none !important; }
    html { scroll-behavior:smooth; scroll-padding-top:32px; }
    body { margin:0; background:var(--paper); color:var(--ink); font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; -webkit-font-smoothing:antialiased; }
    a { color:inherit; text-decoration:none; }
    a,button { -webkit-tap-highlight-color:transparent; }
    a:focus-visible,button:focus-visible { outline:3px solid var(--accent); outline-offset:5px; }
    button { font:inherit; border-radius:0; }
    ::selection { background:var(--ink); color:var(--paper); }
    .shell { width:100%; max-width:1728px; margin-inline:auto; padding-inline:var(--gutter); }
    .masthead { min-height:112px; display:flex; align-items:center; justify-content:space-between; gap:24px; border-bottom:1px solid var(--rule); }
    .brand { display:flex; align-items:center; gap:12px; font-size:19px; font-weight:750; letter-spacing:.065em; white-space:nowrap; }
    .brand-mark { display:block; width:16px; height:22px; background:var(--accent); position:relative; }
    .brand-mark::after { content:""; position:absolute; inset:5px 4px; border-block:1px solid var(--paper); }
    nav { display:flex; align-items:center; gap:clamp(20px,3.3vw,52px); }
    nav a { display:inline-flex; align-items:center; min-height:44px; font-size:14px; font-weight:550; position:relative; }
    nav a::after { content:""; position:absolute; left:0; right:0; bottom:8px; height:1px; background:var(--accent); transform:scaleX(0); transform-origin:left; transition:transform 160ms ease-out; }
    nav a:hover::after,nav a:focus-visible::after { transform:scaleX(1); }
    .hero { padding-top:65px; }
    .intro { display:grid; grid-template-columns:minmax(0,1fr) 235px; align-items:end; gap:40px; padding-bottom:48px; }
    h1 { margin:0; font-size:clamp(64px,7.8vw,120px); font-weight:480; line-height:1.01; letter-spacing:-.066em; }
    h1 span { display:block; }
    .hero-detail { padding-bottom:6px; }
    .hero-detail p { margin:0 0 26px; max-width:250px; font-size:17px; line-height:1.55; letter-spacing:-.015em; }
    .primary { min-height:52px; padding:0 18px; display:inline-flex; justify-content:space-between; align-items:center; gap:25px; background:var(--accent); color:var(--paper); font-size:13px; font-weight:600; transition:background 160ms ease-out; }
    .primary:hover { background:var(--ink); }
    .arrow { width:18px; height:18px; flex:none; }
    .film { position:relative; aspect-ratio:2.65; background:var(--ink); overflow:hidden; isolation:isolate; }
    .film img,.film video { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; object-position:70% 50%; }
    .film img { z-index:-2; }
    .film video { z-index:-1; }
    .motion { position:absolute; right:20px; bottom:20px; min-width:132px; min-height:44px; padding:10px 14px; background:var(--paper); color:var(--ink); border:1px solid var(--paper); display:flex; align-items:center; justify-content:center; gap:10px; font-size:12px; font-weight:600; cursor:pointer; }
    .motion:hover { background:var(--ink); color:var(--paper); }
    .motion:focus-visible { outline-color:var(--paper); box-shadow:0 0 0 8px var(--ink); }
    .motion-icon { width:10px; height:12px; border-inline:3px solid currentColor; }
    .motion[data-paused="true"] .motion-icon { height:0; width:0; border:6px solid transparent; border-left:9px solid currentColor; border-right:0; }
    .work { display:grid; grid-template-columns:1fr 2fr; gap:48px; padding-block:88px 90px; }
    h2 { margin:0; padding-top:21px; font-size:12px; line-height:1.5; font-weight:650; text-transform:uppercase; letter-spacing:.1em; }
    .work-list { list-style:none; padding:0; margin:0; border-top:1px solid var(--rule); }
    .work-list li { display:flex; align-items:baseline; justify-content:space-between; gap:24px; padding-block:23px 27px; border-bottom:1px solid var(--rule); font-size:clamp(26px,2.65vw,40px); font-weight:450; letter-spacing:-.045em; }
    .year { font-size:14px; letter-spacing:0; font-weight:450; white-space:nowrap; }
    .about { border-top:1px solid var(--rule); padding-block:44px 74px; display:grid; grid-template-columns:1fr 2fr; gap:48px; }
    .about::before { content:""; width:20px; height:20px; background:var(--accent); margin-top:10px; }
    .about p { max-width:690px; margin:0; font-size:clamp(32px,4.2vw,62px); line-height:1.15; letter-spacing:-.05em; font-weight:450; }
    @media (min-width:1600px) { .intro { grid-template-columns:minmax(0,1fr) 280px; } }
    @media (max-width:1100px) {
      .intro { grid-template-columns:1fr; gap:28px; }
      h1 { font-size:clamp(64px,10.3vw,108px); }
      .hero-detail { display:flex; align-items:center; justify-content:space-between; gap:32px; padding:0; }
      .hero-detail p { max-width:320px; margin:0; }
      .film { aspect-ratio:2; }
    }
    @media (max-width:600px) {
      .masthead { min-height:94px; align-items:center; flex-wrap:wrap; gap:8px 18px; padding-block:19px 13px; }
      .brand { width:100%; font-size:16px; gap:9px; }
      .brand-mark { width:12px; height:17px; }
      .brand-mark::after { inset:4px 3px; }
      nav { gap:30px; }
      nav a { font-size:12px; }
      .hero { padding-top:37px; }
      .intro { gap:24px; padding-bottom:30px; }
      h1 { font-size:clamp(52px,14.9vw,82px); line-height:1.035; letter-spacing:-.065em; }
      h1 span { display:inline; }
      .hero-detail { display:block; }
      .hero-detail p { max-width:270px; font-size:16px; line-height:1.5; margin-bottom:24px; }
      .primary { min-height:50px; gap:37px; }
      .film { aspect-ratio:1.18; }
      .motion { right:12px; bottom:12px; }
      .work { grid-template-columns:1fr; gap:22px; padding-block:48px 52px; }
      h2 { padding-top:0; }
      .work-list li { padding-block:22px; font-size:29px; }
      .year { font-size:12px; }
      .about { grid-template-columns:20px 1fr; gap:22px; padding-block:30px 48px; }
      .about p { font-size:34px; }
      .about::before { width:12px; height:12px; margin-top:8px; }
    }
    @media (max-height:500px) and (min-width:601px) {
      .masthead { min-height:76px; }
      .hero { padding-top:30px; }
      h1 { font-size:clamp(56px,8vw,78px); }
      .intro { padding-bottom:30px; gap:20px; }
      .film { aspect-ratio:2.65; }
    }
    @media (prefers-reduced-motion:reduce) {
      html { scroll-behavior:auto; }
      *,*::before,*::after { transition:none !important; }
      .film video,.motion { display:none !important; }
    }
  </style>
</head>
<body>
  <div class="shell">
    <header class="masthead">
      <div class="brand"><span class="brand-mark" aria-hidden="true"></span>FIELD NOTES</div>
      <nav aria-label="Main navigation">
        <a href="#work">Work</a>
        <a href="#about">About</a>
        <a href="mailto:studio@example.test">Contact</a>
      </nav>
    </header>
    <main>
      <section class="hero" aria-labelledby="hero-title">
        <div class="intro">
          <h1 id="hero-title"><span>Make room for</span> <span>the moving world.</span></h1>
          <div class="hero-detail">
            <p>Thoughtful films, clear stories, lasting places.</p>
            <a class="primary" href="#work">Explore the work <svg class="arrow" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.5"/></svg></a>
          </div>
        </div>
        <div class="film" data-media>
          <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
          <video src="assets/scene.webm" poster="assets/poster.svg" muted playsinline loop preload="none" aria-hidden="true" hidden></video>
          <button class="motion" type="button" hidden><span class="motion-icon" aria-hidden="true"></span><span data-label>Pause motion</span></button>
        </div>
      </section>
      <section class="work" id="work" aria-labelledby="work-title">
        <h2 id="work-title">Selected work</h2>
        <ul class="work-list">
          <li><span>Tidal study</span> <span class="year">/ 2026</span></li>
          <li><span>Mountain light</span> <span class="year">/ 2025</span></li>
        </ul>
      </section>
      <section class="about" id="about" aria-label="About"><p>An independent film practice.</p></section>
    </main>
  </div>
  <script>
    (() => {
      const root = document.querySelector('[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('button');
      const label = button.querySelector('[data-label]');
      const reduced = matchMedia('(prefers-reduced-motion: reduce)');
      let visible = false, userPaused = false, failed = false, disposed = false, epoch = 0;
      let observer;
      const events = new AbortController();
      const options = { signal: events.signal };
      const still = () => {
        epoch++;
        video.pause();
        video.hidden = true;
        label.textContent = 'Play motion';
        button.dataset.paused = 'true';
      };
      const sync = async () => {
        button.hidden = reduced.matches || failed || disposed;
        if (disposed || reduced.matches || failed || !visible || userPaused || document.hidden) {
          still();
          return;
        }
        const attempt = ++epoch;
        try {
          await video.play();
          if (attempt !== epoch) return;
          video.hidden = false;
          label.textContent = 'Pause motion';
          button.dataset.paused = 'false';
        } catch {
          if (attempt !== epoch) return;
          // A rejected autoplay attempt retains a deliberate keyboard/touch retry.
          still();
        }
      };
      const destroy = () => {
        disposed = true;
        still();
        button.hidden = true;
        observer?.disconnect();
        events.abort();
      };
      try {
        if (!('IntersectionObserver' in window) || !video.canPlayType('video/webm')) return;
        video.muted = true;
        button.addEventListener('click', () => {
          userPaused = !video.paused;
          sync();
        }, options);
        video.addEventListener('error', () => { failed = true; sync(); }, options);
        reduced.addEventListener('change', sync, options);
        document.addEventListener('visibilitychange', sync, options);
        observer = new IntersectionObserver(([entry]) => {
          visible = entry.isIntersecting;
          sync();
        }, { threshold:0 });
        observer.observe(root);
        window.addEventListener('pagehide', (event) => {
          if (event.persisted) { visible = false; sync(); }
          else destroy();
        }, options);
        window.addEventListener('pageshow', (event) => {
          if (event.persisted) { observer.unobserve(root); observer.observe(root); }
        }, options);
      } catch { destroy(); }
    })();
  </script>
</body>
</html>
