try{console.log('Reduced command',await send('emulation.setUserAgentOverride',{contexts:[context],userAgent:null}));}catch(e){console.log('unneeded emulation unsupported',e.error);}
await fs.writeFile('.verification/session.json',JSON.stringify({context,sessionId:session.sessionId}));
console.log('Page logs',logs);
